#!/usr/bin/env python3
"""Materialize the two large frozen WS-29 JSON artifacts byte-for-byte.

The payloads are gzip-compressed copies of the already generated provider-neutral
WS-29 artifacts. The script verifies the required SHA-256 before writing them.
It performs no network access and does not derive or modify authority semantics.
"""
from __future__ import annotations

import base64
import gzip
import hashlib
from pathlib import Path

ARTIFACTS = {
    "CARD_AUTHORITY_LEDGER.json": (
        "a810c9262597db5a1162c6fd8240bd154938e98efe58b0e0cddb29541344e3c4",
        "",
    ),
    "PROVIDER_NEUTRAL_EXPECTED_SEMANTICS.json": (
        "bde2177e91fe9ed0e0399e1637d3b47226c402bfe2c0350cf6bccf87f19c5201",
        "",
    ),
}


def main() -> int:
    target = Path("qualification/ws29")
    target.mkdir(parents=True, exist_ok=True)
    for name, (expected_sha, payload) in ARTIFACTS.items():
        raw = gzip.decompress(base64.b64decode(payload))
        actual = hashlib.sha256(raw).hexdigest()
        if actual != expected_sha:
            raise SystemExit(f"{name}: embedded payload SHA mismatch: {actual} != {expected_sha}")
        path = target / name
        path.write_bytes(raw)
        written = hashlib.sha256(path.read_bytes()).hexdigest()
        if written != expected_sha:
            raise SystemExit(f"{name}: written SHA mismatch: {written} != {expected_sha}")
        print(f"{expected_sha}  {path}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
